  "validate.logout"?: boolean;
  /**
   * Not set: the SP's value, then off.
   */
  "redirect.validate"?: boolean;
  /**
   * Not set: the SP's value, then off.
   */
  "assertion.encryption"?: boolean;
  /**
   * Not set: assertions are decrypted with the SP's private key.
   */
  sharedkey?: string;
  /**
   * Not set: the SP's value, then AES128-GCM.
   */
  sharedkey_algorithm?:
    | "http://www.w3.org/2009/xmlenc11#aes128-gcm"
    | "http://www.w3.org/2009/xmlenc11#aes192-gcm"
    | "http://www.w3.org/2009/xmlenc11#aes256-gcm"
    | "http://www.w3.org/2001/04/xmlenc#aes128-cbc"
    | "http://www.w3.org/2001/04/xmlenc#aes192-cbc"
    | "http://www.w3.org/2001/04/xmlenc#aes256-cbc"
    | "http://www.w3.org/2001/04/xmlenc#tripledes-cbc";
  /**
   * One algorithm URI per line. Not set: the SP's value, then RSA 1.5.
   *
   * @minItems 1
   */
  "encryption.blacklisted-algorithms"?: string[];
  /**
   * Not set: every attribute.
   *
   * @minItems 1
   */
  attributes?: {
    name: string;
    /**
     * One per line.
     *
     * @minItems 1
     */
    values?: string[];
  }[];
  /**
   * One per line. Applied only when the core:AttributeLimit filter runs.
   *
   * @minItems 1
   */
